-- ============================================================================
-- STAGING SETUP — run ONCE on a fresh Supabase project, right after
-- supabase_schema.sql. See database/STAGING_SETUP.md for the full order.
-- ----------------------------------------------------------------------------
-- Everything here is configuration a brand-new project lacks but production
-- already has: API grants, the single company_settings row, and the
-- custom_roles rows. Safe to re-run (every statement is an upsert or a
-- no-op the second time) — but it RESETS the six seeded roles' permissions
-- to the values below, so never run it against production.
-- ============================================================================

-- 0. Refuse to run anywhere that already has real history. A fresh staging
--    project has no green coffee lots older than this setup; production has
--    hundreds going back to July 2026.
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM public.green_coffee_lots WHERE created_at < TIMESTAMPTZ '2026-10-01')
       OR EXISTS (SELECT 1 FROM public.request_orders WHERE created_at < TIMESTAMPTZ '2026-10-01') THEN
        RAISE EXCEPTION 'This database has data from before 2026-10-01 — it looks like production. staging_setup.sql stopped without changing anything.';
    END IF;
END $$;

-- 1. API access. Supabase normally grants these through default privileges,
--    but newer projects can be created with the Data API not exposing new
--    tables automatically. Granting explicitly makes the app work either way.
--    Authorization is enforced client-side (custom_roles) — see CLAUDE.md.
GRANT USAGE ON SCHEMA public TO anon, authenticated;
GRANT ALL ON ALL TABLES IN SCHEMA public TO anon, authenticated;
GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO anon, authenticated;
GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA public TO anon, authenticated;

-- 2. Company settings — the app shows the onboarding overlay when row id = 1
--    is missing. company_name doubles as the marker seed_demo.sql checks
--    before it wipes anything.
INSERT INTO public.company_settings (id, company_name, slogan, currency, weight_unit, address, phone, email)
VALUES (1, 'Demo Roastery (Hackathon)', 'Staging copy — demo data only', 'USD', 'kg',
        'Jl. Kopi No. 1, Jakarta', '+62 21 0000 0000', 'hello@demo-roastery.test')
ON CONFLICT (id) DO UPDATE
SET company_name = EXCLUDED.company_name,
    slogan = EXCLUDED.slogan;
SELECT setval(pg_get_serial_sequence('public.company_settings', 'id'),
              GREATEST((SELECT MAX(id) FROM public.company_settings), 1));

